              "ordinal": 2,
              "text": "[Document context]\nTitle: vLLM KV-cache dtype CPU configuration tests\nSource: vllm pinned workspace\nPath: /code/vllm/tests/utils_/test_torch_utils.py\nWorkspace: task/jamal-pierce/vllm-kv-cache-dtype-v2\n\nfinally:\n        child_thread.join(timeout=5)\n        if child_thread.is_alive():\n            pytest.fail(\"Child thread failed to exit properly\")\n\ndef test_current_stream_multithread():\n    if not torch.cuda.is_available():\n        pytest.skip(\"CUDA not available\")\n\nmain_dedicated_stream = current_stream()\n\nassert main_dedicated_stream.cuda_stream != 0, (\n        \"ROCm/CUDA should create a dedicated stream, not use default stream (0x0)\"\n    )\n\nmain_stream_again = current_stream()\n    assert main_stream_again == main_dedicated_stream, (\n        \"Multiple calls to current_stream should return the same dedicated stream\"\n    )\n\n_test_stream_thread(main_dedicated_stream)\n\ndef _model_config(kv_cache_quant_algo=None):\n    quantization_config = {\"quant_method\": \"modelopt\"}\n    if kv_cache_quant_algo is not None:\n        quantization_config[\"kv_cache_quant_algo\"] = kv_cache_quant_algo\n    return SimpleNamespace(\n        hf_config=SimpleNamespace(quantization_config=quantization_config)\n    )\n\n@pytest.mark.parametrize(\"configuration_source\", [\"implicit\", \"explicit\"])\ndef test_auto_kv_cache_dtype_uses_checkpoint_metadata(configuration_source):\n    model_config = _model_config(\"fp8\")\n    configured_dtype = {\"implicit\": \"auto\", \"explicit\": \"auto\"}[configuration_source]\n\nassert resolve_kv_cache_dtype_string(configured_dtype, model_config) == \"fp8_e4m3\"\n\ndef test_auto_kv_cache_dtype_without_checkpoint_metadata_stays_auto():\n    assert resolve_kv_cache_dtype_string(\"auto\", _model_config()) == \"auto\"\n\ndef test_matching_explicit_kv_cache_dtype_is_allowed():\n    model_config = _model_config(\"fp8\")\n\nassert resolve_kv_cache_dtype_string(\"fp8\", model_config) == \"fp8\"\n\ndef test_incompatible_explicit_kv_cache_dtype_fails_during_configuration():\n    model_config = _model_config(\"fp8\")\n\nwith pytest.raises(ValueError, match=\"Use --kv-cache-dtype auto or fp8_e4m3\"):\n        resolve_kv_cache_dtype_string(\"bfloat16\", model_config)",
