              "text": "[Document context]\nTitle: vLLM KV-cache dtype resolution\nSource: vllm pinned workspace\nPath: /code/vllm/vllm/utils/torch_utils.py\nWorkspace: task/jamal-pierce/vllm-kv-cache-dtype-v2\n\n_dtype = None\n    hf_cfg = getattr(model_config, \"hf_config\", None)\n    if hf_cfg is not None:\n        quant_cfg = getattr(hf_cfg, \"quantization_config\", None)\n        if quant_cfg is not None:\n            checkpoint_dtype = get_kv_cache_quant_algo_string(quant_cfg)\n\nif checkpoint_dtype in (None, \"auto\"):\n        return kv_cache_dtype\n\nif kv_cache_dtype == \"auto\":\n        return checkpoint_dtype\n\ncompatible_dtypes = {checkpoint_dtype}\n    if checkpoint_dtype == \"fp8_e4m3\":\n        compatible_dtypes.add(\"fp8\")\n    if kv_cache_dtype not in compatible_dtypes:\n        raise ValueError(\n            f\"--kv-cache-dtype {kv_cache_dtype} is incompatible with the \"\n            f\"checkpoint's kv_cache_quant_algo ({checkpoint_dtype}). Use \"\n            f\"--kv-cache-dtype auto or {checkpoint_dtype}, or use a checkpoint \"\n            \"without quantized KV-cache metadata.\"\n        )\n\nreturn kv_cache_dtype\n\ndef kv_cache_dtype_str_to_dtype(\n    kv_cache_dtype: str, model_config: ModelConfig\n) -> torch.dtype:\n    if kv_cache_dtype == \"auto\":\n        # Model config may not be specified for unit tests, default to float16\n        return model_config.dtype if model_config else torch.half\n    return STR_DTYPE_TO_TORCH_DTYPE[kv_cache_dtype]\n\ndef set_random_seed(seed: int | None) -> None:\n    if seed is not None:\n        random.seed(seed)\n        np.random.seed(seed)\n        torch.manual_seed(seed)\n        from vllm.platforms import current_platform\n\ncurrent_platform.manual_seed_all(seed)\n\ndef nvfp4_kv_cache_full_dim(head_size: int) -> int:\n    \"\"\"Packed last dim for NVFP4 KV cache: fp4 data + fp8 block scales.\"\"\"\n    return head_size // 2 + head_size // 16\n\ndef nvfp4_split_data_scale(\n    kv_side: torch.Tensor,\n) -> tuple[torch.Tensor, torch.Tensor]:\n    \"\"\"Split one side (K or V) of an NVFP4 KV cache into data and scale.",
