class LayerName(OpaqueBase):  # type: ignore[misc]
    """Wraps a module name string for use as a torch opaque type.

When torch >= 2.11, this is registered as a hoisted value-type opaque
    object so that torch.compile lifts it as a graph input instead of baking
    it as a constant.  This avoids per-layer recompilation for custom ops
    that accept layer name strings (attention, MOE, KV cache, etc.).
    """

def __init__(self, value: str):
        self.value = value

def __eq__(self, other):
        return isinstance(other, LayerName) and self.value == other.value

def __hash__(self):
        return hash(self.value)

def __fx_repr__(self):
        return (f"LayerName({self.value!r})", {"LayerName": LayerName})

if HAS_OPAQUE_TYPE:
    from torch._library.opaque_object import register_opaque_type

register_opaque_type(LayerName, typ="value", hoist=True)

# On torch >= 2.11 (with VLLM_USE_LAYERNAME enabled), custom op
# layer_name parameters use LayerName; otherwise they remain plain str.
if TYPE_CHECKING:
    from typing import TypeAlias

LayerNameType: TypeAlias = str | LayerName
else:
    LayerNameType = LayerName if _USE_LAYERNAME else str

def _resolve_layer_name(layer_name: str | LayerName) -> str:
    """Unwrap a LayerName to str, or return str unchanged."""
    return layer_name.value if isinstance(layer_name, LayerName) else layer_name

def _encode_layer_name(layer_name: str) -> str | LayerName:
    """Wrap a str layer name as LayerName when enabled."""
    return LayerName(layer_name) if _USE_LAYERNAME else layer_name","content_hash":"b350cf8cc29f29f432c62549572d10c8879fbe880f6d3a6a0147e0306856f195","chunk_metadata":{"ordinal":22,"document_path":"/code/vllm/vllm/utils/torch_utils.py","document_kind":"source","workspace":"task/jamal-pierce/vllm-kv-cache-dtype-v2","team":""}}},"conflict_id":null,"change_id":"qdrant:12660f14da12da727caa8ca7"},{"table":"knowledge","key":{"id":"enterprise_97b36da892839ccc46c62291:00023"},"change":"modified","before":{"id":"enterprise_97b36da892839ccc46c62291:00023","vector":{"bm25":{"indices":[11875599,44542115,70186382,141330648,210118348,250826051,440359455,448220673,454222729,543800811,605416826,753371676,757424159,766710245,772165269,806276788,926244272,967714644,1009084850,1075114912,1234765051,1263925004,1331432587,1519078073,1539641452,1642882560,1728513269,1734550606,1853176582,1879591379,2031875777],"values":[1.9085056,1.5087061,1.5087061,1.7899253,1.5087061,2.0648406,1.5087061,1.5087061,1.5087061,1.7899253,1.5087061,1.5087061,1.7899253,1.5087061,1.5087061,1.7899253,1.5087061,1.5087061,1.5087061,1.5087061,1.5087061,1.5087061,1.7899253,1.5087061,1.5087061,1.5087061,1.7899253,1.5087061,1.5087061,1.5087061,1.5087061]}},"payload":{"chunk_metadata":{"workspace":"vllm","repository":"vllm","language":"py","document_path":"/code/vllm/vllm/utils/torch_utils.py","document_kind":"source","connector":"codebase","ordinal":23},"text":"[Document context]
