def nvfp4_split_data_scale(
    kv_side: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Split one side (K or V) of an NVFP4 KV cache into data and scale.

The input is a 4D uint8 tensor whose last dimension is
    ``full_dim = data_dim + scale_dim``.  The physical layout within each
    side is ``[data | scale]``, both packed contiguously.

The caller is responsible for slicing K and V from the combined cache
    first (e.g. ``kv_cache.split(num_kv_heads, dim=1)``).

Args:
        kv_side: 4D uint8 tensor ``(B, H, N, full_dim)``.

Returns:
        ``(data, scale)`` where *data* is uint8 and *scale* is
        float8_e4m3fn, both views of the same storage.
    """
    num_pages = kv_side.shape[0]
    dim_1, dim_2 = kv_side.shape[1], kv_side.shape[2]
    full_dim = kv_side.shape[3]
    data_dim = full_dim * 8 // 9
    scale_dim = full_dim - data_dim

data_per_kv = dim_1 * dim_2 * data_dim
    page_bytes = kv_side.stride(0)

# Derive inner strides from the kv_side strides, scaling by the
    # ratio of the target dim to full_dim.  This preserves the physical
    # layout (NHD vs HND) encoded in the input tensor's strides.
    s1 = kv_side.stride(1) * data_dim // full_dim
    s2 = kv_side.stride(2) * data_dim // full_dim
    data_shape = (num_pages, dim_1, dim_2, data_dim)
    data_strides = (page_bytes, s1, s2, 1)","content_hash":"28ed770d43e82f5f7fd9ce774707fe8979fa421e0a6b5e73720f712c44e714d0","chunk_metadata":{"ordinal":11,"document_path":"/code/vllm/vllm/utils/torch_utils.py","document_kind":"source","workspace":"task/jamal-pierce/vllm-kv-cache-dtype-v2","team":""}}},"conflict_id":null,"change_id":"qdrant:1dd3c81664dc72d9641a2e07"},{"table":"knowledge","key":{"id":"enterprise_97b36da892839ccc46c62291:00012"},"change":"modified","before":{"id":"enterprise_97b36da892839ccc46c62291:00012","vector":{"bm25":{"indices":[70186382,152217691,176587294,187109282,250826051,269592360,390626577,448220673,454222729,563226112,605626641,653705362,757424159,766710245,772165269,806276788,830267937,863034212,926244272,930883039,997012898,1039654807,1120495519,1132748958,1263925004,1299665196,1308688855,1331432587,1498185600,1519078073,1587113310,1590456296,1635830395,1728513269,1751311563,1765437805,1853176582],"values":[1.3760078,1.6930708,1.6930708,1.6930708,2.0003552,1.6930708,2.0864177,1.3760078,1.3760078,1.6930708,1.6930708,1.3760078,1.6930708,1.3760078,1.3760078,1.6930708,1.3760078,1.6930708,1.3760078,1.6930708,1.3760078,2.0266283,2.0266283,1.913531,1.3760078,1.3760078,1.3760078,1.6930708,1.6930708,1.3760078,1.8339304,1.913531,1.3760078,1.6930708,1.3760078,1.3760078,1.3760078]}},"payload":{"content_hash":"03394d0c823f5e5e5a7efd4ea05a58706a6151b723c7fcffb1f6c750486955e6","text":"[Document context]
